    path: []const u8,
    raw: []const u8,

    pub fn format(
        self: UrlParts,
        comptime fmt: []const u8,
        options: std.fmt.FormatOptions,
        writer: anytype,
    ) !void {
        _ = fmt;
        _ = options;
        try writer.print(\

, .{ self.raw, self.host, self.port, self.path });
    }
};

const ParseError = error{
    InvalidScheme,
